function.arguments:
{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data.csv')
df['date'] = pd.to_datetime(df['date'])
acc = df[df.account_id=='tVENWJP'].copy()
acc['rkey'] = acc.csp + '|' + acc.cloud_service + '|' + acc.application + '|' + acc.instance_family
d0 = pd.Timestamp('2025-09-22')

# check num_instances and price anomalies: on 9/22, does any resource have price or count different from its history?
day = acc[acc.date==d0]
for k, r in day.iterrows():
    hist = acc[(acc.rkey==r.rkey) & (acc.date!=d0)]
    if (hist['price'] != r['price']).any():
        print('PRICE ANOMALY', r.rkey, 'hist prices', hist['price'].unique(), 'on 9/22:', r['price'])
    if not hist['num_instances'].isin([r['num_instances']]).all():
        pass  # counts vary normally

# check count: compare 9/22 count to same weekday (Tuesday) counts
tues = [pd.Timestamp('2025-09-16'), pd.Timestamp('2025-09-30')]
for k, r in day.iterrows():
    hist = acc[(acc.rkey==r.rkey) & (acc.date.isin(tues))]
    if len(hist)>0 and r['num_instances'] not in hist['num_instances'].values:
        print('COUNT DIFF vs Tuesdays:', r.rkey, '9/22 count', r['num_instances'], 'tue counts', hist['num_instances'].tolist())"}
